class Solution {
    public int countPrimes(int n) {
        int count = 0;
        for (int i = 2; i < n; i++) {
            if (isPrime(i)) count++;
        }
        return count;
    }

    private boolean isPrime(int x) {
        if (x < 2) return false;
        for (int d = 2; d <= x / d; d++) {
            if (x % d == 0) return false;
        }
        return true;
    }
}

class Solution {
    public int countPrimes(int n) {
        if (n < 2) return 0;
        boolean[] notPrime = new boolean[n];
        for (int i = 2; i < n / i; i++) {
            if (!notPrime[i]) {
                for (long j = (long) i * i; j < n; j += i) {
                    notPrime[(int) j] = true;
                }
            }
        }

        int count = 0;
        for (int i = 2; i < n; i++) {
            if (!notPrime[i]) count++;
        }
        return count;
    }
}

import java.util.*;

class Solution {
    public int countPrimes(int n) {
        if (n < 2) return 0;
        boolean[] composite = new boolean[n];
        List<Integer> primes = new ArrayList<>();

        for (int i = 2; i < n; i++) {
            if (!composite[i]) primes.add(i);
            for (int p : primes) {
                if ((long) i * p >= n) break;
                composite[i * p] = true;
                if (i % p == 0) break;
            }
        }
        return primes.size();
    }
}
